def majority_element(nums):
    """
    Finds the majority element in an array.

    Args:
        nums: A list of integers.

    Returns:
        The majority element in the array.
    """
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    for num, count in counts.items():
        if count > len(nums) // 2:
            return num
