def longest_wiggle_subsequence(nums):
    """
    Finds the length of the longest wiggle subsequence of nums.

    Args:
        nums: An integer array.

    Returns:
        The length of the longest wiggle subsequence of nums.
    """

    if len(nums) <= 1:
        return len(nums)

    n = len(nums)
    up = 1
    down = 1

    for i in range(1, n):
        if nums[i] > nums[i - 1]:
            up = down + 1
        elif nums[i] < nums[i - 1]:
            down = up + 1

    return max(up, down)
