def max_distance(arrays):
    """
    Calculates the maximum distance between two integers picked from different sorted arrays.

    Args:
        arrays: A list of sorted arrays.

    Returns:
        The maximum distance between two integers picked from different arrays.
    """

    max_dist = 0
    for i in range(len(arrays)):
        for j in range(len(arrays[i])):
            for k in range(len(arrays)):
                if i != k:
                    for l in range(len(arrays[k])):
                        dist = abs(arrays[i][j] - arrays[k][l])
                        max_dist = max(max_dist, dist)
    return max_dist
