def predict_winner(senate):
    """
    Predicts the winner of the Dota2 Senate voting based on the senators' parties.

    Args:
        senate: A string representing the party affiliation of each senator ('R' for Radiant, 'D' for Dire).

    Returns:
        "Radiant" or "Dire", indicating the party that is predicted to win.
    """
    radiant_count = 0
    dire_count = 0
    for senator in senate:
        if senator == 'R':
            radiant_count += 1
        else:
            dire_count += 1

    if radiant_count > dire_count:
        return "Radiant"
    elif dire_count > radiant_count:
        return "Dire"
    else:
        return "Radiant"  # In case of a tie, Radiant wins
