def nearest_node_right(root, u):
    """
    Given the root of a binary tree and a node u in the tree, return the nearest node on the same level that is to the right of u, or return null if u is the rightmost node in its level.

    Args:
        root (TreeNode): The root of the binary tree.
        u (TreeNode): The node to find the nearest node to the right of.

    Returns:
        TreeNode: The nearest node on the same level to the right of u, or null if u is the rightmost node in its level.
    """
    if not root or not u:
        return None

    queue = [(root, 0)]
    level_nodes = {}

    while queue:
        node, level = queue.pop(0)

        if level not in level_nodes:
            level_nodes[level] = []
        level_nodes[level].append(node)

        if node.left:
            queue.append((node.left, level + 1))
        if node.right:
            queue.append((node.right, level + 1))

    if u not in level_nodes:
        return None

    level = level_nodes[u.val].index(u)

    if level == len(level_nodes[u.val]) - 1:
        return None

    return level_nodes[u.val][level + 1]
