    """
    Finds the length of the longest beautiful substring of a given string.

    Args:
        word: The input string consisting of English vowels.

    Returns:
        The length of the longest beautiful substring.
    """

    vowels = "aeiou"
    n = len(word)
    max_len = 0

    for i in range(n):
        for j in range(i, n):
            substring = word[i:j+1]

            vowel_counts = {}
            for char in substring:
                vowel_counts[char] = vowel_counts.get(char, 0) + 1

            has_all_vowels = True
            for vowel in vowels:
                if vowel not in vowel_counts or vowel_counts[vowel] == 0:
                    has_all_vowels = False
                    break

            if has_all_vowels:
                is_sorted = True
                for k in range(len(substring) - 1):
                    if substring[k] > substring[k+1]:
                        is_sorted = False
                        break

                if is_sorted:
                    max_len = max(max_len, len(substring))

    return max_len
