def count_paths(grid, k):
    m = len(grid)
    n = len(grid[0])
    mod = 10**9 + 7
    dp = {}

    def solve(row, col, current_sum):
        if (row, col, current_sum) in dp:
            return dp[(row, col, current_sum)]

        if row == m - 1 and col == n - 1:
            if (current_sum + grid[row][col]) % k == 0:
                return 1
            else:
                return 0

        if row >= m or col >= n:
            return 0

        paths = 0
        paths += solve(row + 1, col, (current_sum + grid[row][col]) % k)
        paths += solve(row, col + 1, (current_sum + grid[row][col]) % k)

        dp[(row, col, current_sum)] = paths % mod
        return dp[(row, col, current_sum)]

    return solve(0, 0, 0)
