def count_complete_substrings(word, k):
    """
    Counts the number of complete substrings of word.

    A substring s of word is complete if:
    - Each character in s occurs exactly k times.
    - The difference between two adjacent characters is at most 2.

    Args:
        word: The input string.
        k: The number of times each character must appear.

    Returns:
        The number of complete substrings of word.
    """

    count = 0
    for i in range(len(word)):
        for j in range(i, len(word)):
            substring = word[i:j+1]

            char_counts = {}
            for char in substring:
                char_counts[char] = char_counts.get(char, 0) + 1

            is_complete = True
            for char in char_counts:
                if char_counts[char] != k:
                    is_complete = False
                    break

            if is_complete:
                is_valid = True
                for l in range(len(substring) - 1):
                    if abs(ord(substring[l]) - ord(substring[l+1])) > 2:
                        is_valid = False
                        break

                if is_valid:
                    count += 1

    return count
